import logging
import os
import threading
from datetime import datetime, timezone
from pathlib import Path
from typing import Dict, List, Optional, Set

from src.wal_codec import WalCodec, JsonlCodec, WalDecodeError, resolve_codec

logger = logging.getLogger(__name__)

STATUS_PENDING = "pending"
STATUS_IN_PROGRESS = "in_progress"
STATUS_COMPLETED = "completed"
STATUS_FAILED = "failed"

DEFAULT_HEARTBEAT_SECONDS = 600
DEFAULT_COMPACT_THRESHOLD = 10000
DEFAULT_MAX_ATTEMPTS = 3


def _generate_microbatch_id() -> str:
    now = datetime.now(timezone.utc)
    date_part = now.strftime("%Y-%m-%d")
    return f"{date_part}-{now.strftime('%H%M%S')}"


class WriteAheadLog:
    """
    Append-only JSONL write-ahead log for batch processing crash recovery.

    Lives at <folder>/.open-photo-agent/wal.jsonl
    """

    def __init__(
        self,
        folder: str,
        codec: Optional[WalCodec] = None,
        codec_name: Optional[str] = None,
        heartbeat_seconds: int = DEFAULT_HEARTBEAT_SECONDS,
        max_attempts: int = DEFAULT_MAX_ATTEMPTS,
        compact_threshold: int = DEFAULT_COMPACT_THRESHOLD,
    ):
        """Open (or create) the WAL for a given folder and load+repair on init.

        On construction the WAL is fully read into an in-memory index.
        Any ``in_progress`` entries older than ``heartbeat_seconds`` are
        automatically reset to ``pending`` (or ``failed`` if the retry
        limit is exceeded).
        """
        self._folder = Path(folder).absolute()
        self._heartbeat_seconds = heartbeat_seconds
        self._max_attempts = max_attempts
        self._compact_threshold = compact_threshold

        if codec is not None:
            self._codec = codec
        else:
            self._codec = self._resolve_codec_from_disk(codec_name)

        self._wal_dir = self._folder / ".open-photo-agent"
        self._path = self._wal_dir / f"wal{self._codec.file_extension}"
        self._lock = threading.Lock()

        self._index: Dict[str, Dict] = {}
        self._seq_counter: int = 0
        self._load_and_repair()

    def _resolve_codec_from_disk(self, codec_name: Optional[str]) -> WalCodec:
        wal_dir = self._folder / ".open-photo-agent"
        for ext, cls in {
            ".jsonl": JsonlCodec,
        }.items():
            candidate = wal_dir / f"wal{ext}"
            if candidate.exists():
                return cls()

        if codec_name:
            if codec_name == "jsonl":
                return JsonlCodec()
            raise ValueError(f"Unknown codec name: {codec_name!r}")
        return JsonlCodec()

    def _load_and_repair(self):
        self._index.clear()
        self._seq_counter = 0

        if not self._path.exists():
            return

        raw_lines = []
        try:
            with open(self._path, "rb") as f:
                raw_lines = f.read().split(b"\n")
        except OSError:
            return

        for line in raw_lines:
            if not line.strip():
                continue
            try:
                entry = self._codec.decode(line)
                img_path = entry.get("image_path", "")
                if img_path:
                    self._index[img_path] = entry
                seq = entry.get("seq", 0)
                if seq > self._seq_counter:
                    self._seq_counter = seq
            except WalDecodeError:
                logger.warning(
                    "Skipping corrupt/truncated WAL line in %s", self._path
                )
                continue

        self._repair_abandoned()

    def _repair_abandoned(self):
        now = datetime.now(timezone.utc)
        reset_count = 0

        for img_path, entry in list(self._index.items()):
            if entry.get("status") != STATUS_IN_PROGRESS:
                continue
            ts_str = entry.get("ts", "")
            try:
                ts = datetime.fromisoformat(ts_str)
            except (ValueError, TypeError):
                continue
            elapsed = (now - ts).total_seconds()
            if elapsed > self._heartbeat_seconds:
                attempt = entry.get("attempt", 1) + 1
                if attempt > self._max_attempts:
                    new_entry = {
                        "seq": self._next_seq(),
                        "image_path": img_path,
                        "status": STATUS_FAILED,
                        "microbatch_id": entry.get("microbatch_id", ""),
                        "ts": now.isoformat(),
                        "attempt": entry.get("attempt", 1),
                        "sidecar_path": entry.get("sidecar_path"),
                        "error_code": "abandoned_heartbeat",
                        "error_msg": f"Abandoned in_progress after {self._heartbeat_seconds}s, max attempts exceeded",
                    }
                else:
                    new_entry = {
                        "seq": self._next_seq(),
                        "image_path": img_path,
                        "status": STATUS_PENDING,
                        "microbatch_id": entry.get("microbatch_id", ""),
                        "ts": now.isoformat(),
                        "attempt": attempt,
                        "sidecar_path": entry.get("sidecar_path"),
                        "error_code": None,
                        "error_msg": None,
                    }
                self._index[img_path] = new_entry
                reset_count += 1
                logger.warning(
                    "Resetting abandoned in_progress entry: %s (attempt %d)",
                    img_path,
                    attempt,
                )

        if reset_count:
            self._rewrite_wal()

    def _next_seq(self) -> int:
        self._seq_counter += 1
        return self._seq_counter

    def _append_raw(self, raw: bytes):
        self._wal_dir.mkdir(parents=True, exist_ok=True)
        try:
            with open(self._path, "ab") as f:
                f.write(raw)
                f.flush()
                os.fsync(f.fileno())
        except OSError as e:
            logger.error("Failed to append to WAL %s: %s", self._path, e)
            raise

    def append(
        self,
        image_path: str,
        status: str,
        microbatch_id: str,
        attempt: int = 1,
        sidecar_path: Optional[str] = None,
        error_code: Optional[str] = None,
        error_msg: Optional[str] = None,
    ) -> int:
        """Append a lifecycle event for an image to the WAL (thread-safe).

        Args:
            image_path: Absolute path to the image file.
            status: One of ``pending``, ``in_progress``, ``completed``, ``failed``.
            microbatch_id: Identifier for the current micro-batch run.
            attempt: Retry attempt number (1-based).
            sidecar_path: Optional path to the corresponding sidecar JSON.
            error_code: Optional error code string on failure.
            error_msg: Optional error message string on failure.

        Returns:
            The monotonically-increasing sequence number of the entry.
        """
        with self._lock:
            entry = {
                "seq": self._next_seq(),
                "image_path": image_path,
                "status": status,
                "microbatch_id": microbatch_id,
                "ts": datetime.now(timezone.utc).isoformat(),
                "attempt": attempt,
                "sidecar_path": sidecar_path,
                "error_code": error_code,
                "error_msg": error_msg,
            }
            self._index[image_path] = entry
            raw = self._codec.encode(entry)
            self._append_raw(raw)
            return entry["seq"]

    def get_status(self, image_path: str) -> Optional[str]:
        """Return the current lifecycle status for a single image, or None."""
        with self._lock:
            entry = self._index.get(image_path)
            if entry is None:
                return None
            return entry.get("status")

    def get_pending(self) -> List[str]:
        """Return paths of all images in pending or in_progress state."""
        with self._lock:
            return [
                path
                for path, entry in self._index.items()
                if entry.get("status") in (STATUS_PENDING, STATUS_IN_PROGRESS)
            ]

    def get_completed_set(self) -> Set[str]:
        """Return a set of image paths that have been successfully completed."""
        with self._lock:
            return {
                path
                for path, entry in self._index.items()
                if entry.get("status") == STATUS_COMPLETED
            }

    def get_failed(self) -> List[dict]:
        """Return a list of failed entries with path, error_code, and error_msg."""
        with self._lock:
            return [
                {
                    "image_path": entry.get("image_path"),
                    "error_code": entry.get("error_code"),
                    "error_msg": entry.get("error_msg"),
                }
                for entry in self._index.values()
                if entry.get("status") == STATUS_FAILED
            ]

    def get_active_microbatch_id(self) -> Optional[str]:
        """Return the microbatch_id of any in-flight (pending/in_progress) entry."""
        with self._lock:
            for entry in self._index.values():
                if entry.get("status") in (STATUS_PENDING, STATUS_IN_PROGRESS):
                    return entry.get("microbatch_id")
            return None

    def get_stats(self) -> Dict:
        """Return aggregate counts: total, completed, failed, pending."""
        with self._lock:
            total = len(self._index)
            completed = sum(
                1 for e in self._index.values() if e.get("status") == STATUS_COMPLETED
            )
            failed = sum(
                1 for e in self._index.values() if e.get("status") == STATUS_FAILED
            )
            pending = sum(
                1
                for e in self._index.values()
                if e.get("status") in (STATUS_PENDING, STATUS_IN_PROGRESS)
            )
            return {
                "total": total,
                "completed": completed,
                "failed": failed,
                "pending": pending,
            }

    def prune(self, keep_completed: bool = True) -> int:
        """Remove failed (and optionally completed) entries and rewrite the WAL.

        Returns the number of entries removed.
        """
        with self._lock:
            removed = 0
            to_keep: Dict[str, Dict] = {}
            for path, entry in self._index.items():
                status = entry.get("status")
                if status == STATUS_COMPLETED and keep_completed:
                    to_keep[path] = entry
                elif status == STATUS_COMPLETED and not keep_completed:
                    removed += 1
                elif status == STATUS_FAILED:
                    removed += 1
                else:
                    to_keep[path] = entry
            self._index = to_keep
            self._rewrite_wal()
            return removed

    def compact(self) -> int:
        """Rewrite the WAL keeping only the latest entry per image.

        Returns the number of entries before compaction.
        """
        with self._lock:
            old_count = len(self._index)
            self._rewrite_wal()
            return old_count

    def auto_compact_if_needed(self) -> bool:
        """Compact the WAL if the entry count exceeds the configured threshold.

        Returns True if compaction was performed.
        """
        with self._lock:
            line_count = len(self._index)
            if line_count > self._compact_threshold:
                logger.info(
                    "WAL has %d entries (>%d), auto-compacting...",
                    line_count,
                    self._compact_threshold,
                )
                self._rewrite_wal()
                return True
            return False

    def _rewrite_wal(self):
        self._wal_dir.mkdir(parents=True, exist_ok=True)
        tmp_path = self._path.with_suffix(".tmp")
        try:
            with open(tmp_path, "wb") as f:
                for entry in sorted(
                    self._index.values(), key=lambda e: e.get("seq", 0)
                ):
                    f.write(self._codec.encode(entry))
                    f.flush()
                os.fsync(f.fileno())
            os.replace(tmp_path, self._path)
        except OSError as e:
            logger.error("Failed to rewrite WAL %s: %s", self._path, e)
            if tmp_path.exists():
                try:
                    tmp_path.unlink()
                except OSError:
                    pass
            raise


def generate_microbatch_id() -> str:
    """Create a unique micro-batch ID in ``YYYY-MM-DD-HHMMSS`` format."""
    return _generate_microbatch_id()

import logging
import os
import sqlite3
from pathlib import Path

import dash
import dash_bootstrap_components as dbc
from dash import Input, Output, State, html, dash_table

_WAL_STATS_CACHE: dict = {}

from src.interfaces import ProcessingResult, ErrorCode
from src.discovery import PhotoList
from src.batch_state import write_batch_state, read_batch_state, clear_batch_state
from src.coordinator import (
    BatchCoordinator,
    ProcessingConfig,
    ExtractorProvider,
    PromptResolver,
    SequentialStrategy,
    WALSequentialStrategy,
    FileProgressReporter,
    CollectingSidecarSaver,
    FolderImageSource,
)
from src.components import build_folder_controls
from src.utils import compute_duration_stats
from src.state import request_shutdown, reset_shutdown_event, is_shutdown_requested
from src.config import AppConfig
from src.sidecar.database import FeaturesDatabase

logger = logging.getLogger(__name__)


def _get_extractor(provider: ExtractorProvider, host: str, port: str, model: str, timeout: str, backend: str = "ollama"):
    """Coerce form values and return a cached extractor from the provider."""
    timeout_int = int(timeout) if timeout else 120
    port_int = int(port) if port else 11434
    used_host = host or "192.168.0.29"
    used_model = model or "gemma4:e2b"
    return provider.get(
        host=used_host,
        port=port_int,
        model=used_model,
        timeout=timeout_int,
        backend=backend,
    )


def _make_processing_config(host, port, model, backend, timeout, default_prompt, dry_run=False) -> ProcessingConfig:
    """Build a ProcessingConfig from loosely-typed form/state values."""
    return ProcessingConfig(
        backend="dry_run" if dry_run else (backend or "ollama"),
        host=host,
        port=int(port) if port else 11434,
        model=model,
        timeout=int(timeout) if timeout else 120,
        default_prompt=default_prompt,
    )


def _make_wal_strategy(folder, app_config):
    return WALSequentialStrategy(
        folder,
        heartbeat_seconds=app_config.wal_heartbeat_seconds,
        max_attempts=app_config.wal_max_attempts,
        compact_threshold=app_config.wal_compact_threshold,
    )


def register_folder_callback(app):
    @app.callback(
        Output("folder-file-list", "children"),
        Output("folder-cache", "data"),
        Input("input-folder", "value"),
        Input("btn-rescan", "n_clicks"),
        State("chk-recursive", "value"),
    )
    def update_folder_list(folder, n_clicks, recursive):
        if not folder:
            return dbc.Badge("Enter a folder path", color="secondary"), {}

        try:
            source = FolderImageSource(folder, recursive=bool(recursive), exclude_processed=True)
            image_paths = source.list_images(limit=10)
            total_remaining = source.total_pending()
            total_all = source.total_all()
            pending = min(total_remaining, 10)

            cache_data = {
                "folder": folder,
                "recursive": recursive,
                "total_all": total_all,
                "total_remaining": total_remaining,
            }

            if not image_paths:
                return html.Div("No new images found in this folder.", className="text-muted"), cache_data

            return build_folder_controls(image_paths, pending, total_remaining), cache_data
        except Exception as e:
            return html.Div(f"Error listing folder: {e}", className="text-danger"), {}


def register_toggle_callback(app):
    @app.callback(
        Output("folder-files-collapse", "is_open"),
        Input("btn-toggle-files", "n_clicks"),
        State("folder-files-collapse", "is_open"),
        prevent_initial_call=True,
    )
    def toggle_file_list(n_clicks, is_open):
        if n_clicks is None:
            return dash.no_update
        return not is_open


def register_batch_callback(app, default_prompt, app_config):
    @app.callback(
        Output("processing-status", "children"),
        Input("btn-process-batch", "n_clicks"),
        State("input-folder", "value"),
        State("chk-recursive", "value"),
        State("input-prompt", "value"),
        State("input-host", "value"),
        State("input-port", "value"),
        State("input-model", "value"),
        State("input-backend", "value"),
        State("input-timeout", "value"),
        State("chk-dry-run", "value"),
        background=True,
        prevent_initial_call=True,
        running=[
            (Output("btn-process-batch", "disabled"), True, False),
            (Output("btn-process-all", "disabled"), True, False),
        ],
    )
    def queue_all_images(n_clicks, folder, recursive, prompt, host, port, model, backend, timeout, dry_run):
        if not n_clicks or not folder:
            return dash.no_update

        source = FolderImageSource(folder, recursive=bool(recursive), exclude_processed=True)
        image_paths = source.list_images(limit=10)
        if not image_paths:
            return "No new images to process."

        pc = _make_processing_config(host, port, model, backend, timeout, default_prompt, dry_run=bool(dry_run))
        strategy = _make_wal_strategy(folder, app_config)
        reporter = FileProgressReporter(folder)
        collector = CollectingSidecarSaver()

        batch_coordinator = BatchCoordinator(config=pc, strategy=strategy)
        batch_coordinator.run_folder_batch(
            folder,
            recursive=bool(recursive),
            prompt=prompt,
            limit=10,
            saver=collector,
            reporter=reporter,
        )

        prefix = "Dry-run" if dry_run else "Batch"
        return f"{prefix} complete."


def register_process_all_callback(app, default_prompt, app_config):
    @app.callback(
        Output("processing-status", "children", allow_duplicate=True),
        Input("btn-process-all", "n_clicks"),
        State("input-folder", "value"),
        State("chk-recursive", "value"),
        State("input-prompt", "value"),
        State("input-host", "value"),
        State("input-port", "value"),
        State("input-model", "value"),
        State("input-backend", "value"),
        State("input-timeout", "value"),
        State("chk-dry-run", "value"),
        background=True,
        prevent_initial_call=True,
        running=[
            (Output("btn-process-all", "disabled"), True, False),
            (Output("btn-process-batch", "disabled"), True, False),
            (Output("btn-stop-all", "disabled"), False, True),
            (Output("btn-rescan", "disabled"), True, False),
        ],
    )
    def process_all_images(n_clicks, folder, recursive, prompt, host, port, model, backend, timeout, dry_run):
        if not n_clicks or not folder:
            return dash.no_update

        existing_state = read_batch_state(folder)
        if existing_state and existing_state.get("status") in ("running_all", "running"):
            return "A batch is already running for this folder."

        reset_shutdown_event()

        pc = _make_processing_config(host, port, model, backend, timeout, default_prompt, dry_run=bool(dry_run))
        strategy = _make_wal_strategy(folder, app_config)

        source_all = FolderImageSource(folder, recursive=bool(recursive), exclude_processed=False)
        total_all = source_all.total_pending()

        write_batch_state(folder, "running_all", total_all, 0, status_msg="Process All started")

        batch_num = 0
        total_processed = 0
        all_durations = []
        consecutive_errors = 0
        MAX_CONSECUTIVE_ERRORS = 3

        while True:
            if is_shutdown_requested():
                write_batch_state(folder, "aborted", total_all, total_processed,
                                  status_msg="Process All aborted by user")
                return f"Process All aborted. {total_processed} images processed."

            collector = CollectingSidecarSaver()
            reporter = FileProgressReporter(folder)
            batch_coordinator = BatchCoordinator(config=pc, strategy=strategy)

            try:
                stats = batch_coordinator.run_folder_batch(
                    folder,
                    recursive=bool(recursive),
                    prompt=prompt,
                    limit=10,
                    saver=collector,
                    reporter=reporter,
                )
            except Exception as e:
                logger.error("Batch %d failed with error: %s", batch_num + 1, e)
                consecutive_errors += 1
                if consecutive_errors >= MAX_CONSECUTIVE_ERRORS:
                    logger.error("Too many consecutive errors (%d), aborting.", consecutive_errors)
                    write_batch_state(folder, "aborted", total_all, total_processed,
                                      status_msg=f"Aborted after {consecutive_errors} consecutive errors")
                    return f"Process All aborted after {consecutive_errors} consecutive errors."
                continue

            if stats.total == 0:
                break

            batch_num += 1
            total_processed += stats.success_count + stats.failure_count

            for result_dict in collector.results:
                if result_dict.get("success") and result_dict.get("total_duration_ms") is not None:
                    all_durations.append(result_dict["total_duration_ms"])

            if stats.failure_count > 0:
                consecutive_errors += stats.failure_count
            else:
                consecutive_errors = 0

            if consecutive_errors >= MAX_CONSECUTIVE_ERRORS:
                logger.error("Too many consecutive errors (%d), aborting.", consecutive_errors)
                write_batch_state(folder, "aborted", total_all, total_processed,
                                  status_msg=f"Aborted after {consecutive_errors} consecutive errors")
                return f"Process All aborted after {consecutive_errors} consecutive errors."

            write_batch_state(folder, "running_all", total_all, total_processed,
                              status_msg=f"Batch {batch_num}: {total_processed}/{total_all}")

        dur_stats = compute_duration_stats(all_durations)
        write_batch_state(folder, "done_all", total_all, total_processed,
                          avg_duration_ms=dur_stats["avg_ms"],
                          min_duration_ms=dur_stats["min_ms"],
                          max_duration_ms=dur_stats["max_ms"],
                          total_model_time_s=dur_stats["total_s"],
                          status_msg=f"All {total_processed} images processed")

        prefix = "Dry-run" if dry_run else "Process All"
        return f"{prefix} complete. {total_processed} images processed."


def register_stop_callback(app):
    @app.callback(
        Output("btn-stop-all", "disabled", allow_duplicate=True),
        Input("btn-stop-all", "n_clicks"),
        prevent_initial_call=True,
    )
    def stop_all(n_clicks):
        if n_clicks:
            request_shutdown()
        return True


def register_health_callback(app, provider):
    @app.callback(
        Output("health-status", "children"),
        Input("btn-health", "n_clicks"),
        State("input-host", "value"),
        State("input-port", "value"),
        State("input-model", "value"),
        State("input-backend", "value"),
        State("input-timeout", "value"),
        State("chk-dry-run", "value"),
        prevent_initial_call=True,
    )
    def check_health(n_clicks, host, port, model, backend, timeout, dry_run):
        if n_clicks is None:
            return dash.no_update

        if dry_run:
            return dbc.Alert(
                "Dry-run mode active — no LLM connectivity needed.",
                color="info",
                dismissable=True,
            )

        extractor = _get_extractor(provider, host, port, model, timeout, backend)
        if extractor.health_check():
            return dbc.Alert(
                f"LLM server is reachable at {extractor.base_url} (model: {extractor.model})",
                color="success",
                dismissable=True,
            )
        else:
            return dbc.Alert(
                f"Cannot reach LLM at {extractor.base_url}. Please check your settings.",
                color="danger",
                dismissable=True,
            )


def register_polling_callback(app):
    @app.callback(
        Output("queue-status", "children"),
        Input("poll-interval", "n_intervals"),
        State("input-folder", "value"),
        State("chk-recursive", "value"),
        State("folder-cache", "data"),
    )
    def poll_queue_status(n_intervals, folder, recursive, cache_data):
        if not folder:
            return dbc.Badge("No folder set", color="secondary")
        try:
            state = read_batch_state(folder)
            if state:
                status = state.get("status")
                total = state.get("total", 0)
                completed = state.get("completed", 0)

                if status == "running":
                    return dbc.Badge(
                        f"Processing — {completed}/{total}", color="warning"
                    )
                if status == "running_all":
                    status_msg = state.get("status_msg", "")
                    batch_display = status_msg if status_msg else f"Processing All — {completed}/{total}"
                    return dbc.Badge(batch_display, color="info")
                if status == "done":
                    avg_ms = state.get("avg_duration_ms", 0)
                    total_s = state.get("total_model_time_s", 0)
                    cnt = state.get("completed", total)
                    if avg_ms and total_s:
                        return dbc.Badge(
                            f"Batch complete — {cnt} processed · avg {avg_ms:.0f} ms/photo · {total_s:.1f}s total",
                            color="success",
                        )
                    return dbc.Badge(f"Batch complete — {cnt} processed", color="success")
                if status == "done_all":
                    avg_ms = state.get("avg_duration_ms", 0)
                    total_s = state.get("total_model_time_s", 0)
                    cnt = state.get("completed", total)
                    if avg_ms and total_s:
                        return dbc.Badge(
                            f"Complete — {cnt} processed · avg {avg_ms:.0f} ms/photo · {total_s:.1f}s total",
                            color="success",
                        )
                    return dbc.Badge(f"Complete — {cnt} processed", color="success")
                if status == "aborted":
                    return dbc.Badge(
                        f"Aborted — {completed}/{total} processed", color="danger"
                    )

            wal_stats, wal_stats_ts = _WAL_STATS_CACHE.get(folder, (None, 0))
            try:
                wal_path = Path(folder) / ".open-photo-agent" / "wal.jsonl"
                if wal_path.exists():
                    wal_mtime = wal_path.stat().st_mtime
                    if wal_stats is None or wal_mtime != wal_stats_ts:
                        from src.wal import WriteAheadLog
                        wal = WriteAheadLog(folder)
                        wal_stats = wal.get_stats()
                        _WAL_STATS_CACHE[folder] = (wal_stats, wal_mtime)
            except OSError:
                pass
            if wal_stats and wal_stats.get("completed", 0) > 0:
                return dbc.Badge(
                    f"Idle — {wal_stats['completed']} processed, {wal_stats['pending']} pending",
                    color="secondary",
                )

            cache_hit = (
                isinstance(cache_data, dict)
                and cache_data.get("folder") == folder
                and cache_data.get("recursive") == recursive
            )
            if cache_hit:
                total_all = cache_data.get("total_all", 0)
                total_remaining = cache_data.get("total_remaining", 0)
            else:
                source = FolderImageSource(folder, recursive=bool(recursive), exclude_processed=True)
                total_remaining = source.total_pending()
                total_all = source.total_all()

            if total_all == 0:
                return dbc.Badge("No images found in folder", color="secondary")
            if total_remaining == 0:
                return dbc.Badge(f"Complete — {total_all} total", color="success")
            return dbc.Badge(f"Idle — {total_remaining} pending", color="secondary")
        except Exception:
            logger.warning("Failed to read folder status for %s", folder, exc_info=True)
            return dbc.Badge("Error reading status", color="danger")


def register_sql_explorer_callback(app):
    @app.callback(
        Output("sql-results", "children"),
        Input("btn-run-sql", "n_clicks"),
        State("input-folder", "value"),
        State("sql-input", "value"),
        prevent_initial_call=True,
    )
    def run_sql(n_clicks, folder, sql_text):
        if n_clicks is None:
            return dash.no_update

        if not folder:
            return dbc.Alert(
                "Enter a folder path above before running queries.",
                color="warning",
            )

        db_path = FeaturesDatabase.default_db_path(folder)
        if not db_path.exists():
            return dbc.Alert(
                "No features.db found for this folder. Scan the folder first.",
                color="warning",
            )

        db = FeaturesDatabase(db_path)
        try:
            columns, rows = db.execute_query(sql_text)
        except (sqlite3.Error, FileNotFoundError, OSError) as e:
            return dbc.Alert(str(e), color="danger")
        finally:
            db.close()

        if not columns:
            return html.Div("Query returned no columns.", className="text-muted")

        if not rows:
            return html.Div("Query returned an empty result set.", className="text-muted")

        return dash_table.DataTable(
            columns=[{"name": c, "id": c} for c in columns],
            data=[dict(zip(columns, row)) for row in rows],
            style_table={"overflowX": "auto"},
            sort_action="native",
            filter_action="native",
            page_action="native",
            page_size=20,
        )


def register_callbacks(app, create_extractor_fn, processing_config, default_prompt: str, app_config: AppConfig):
    """Register all Dash callbacks (folder list, process batch, process all, etc.) on the app."""
    provider = ExtractorProvider(create_extractor_fn)

